UPDATE SYT0YH SET TR_CO_CD=#{trCoCd,jdbcType=VARCHAR}, TRUSTEE=#{trustee,jdbcType=VARCHAR}, JM_CD=#{yjCd,jdbcType=VARCHAR},
    CURRENCY=#{currency,jdbcType=VARCHAR}, GYULJE_AEK=NVL(#{gyuljeAek},0), TRANS_RT=NVL(#{transRt},0),
    WON_GYULJE_AEK=NVL(#{wonGyuljeAek},0), GYULJE_YMD=TO_DATE(REPLACE(#{gyuljeYmd}, '-', ''), 'YYYYMMDD'),
    FCUR_GYULJE_AEK=#{fcurGyuljeAek,jdbcType=NUMERIC}, KSD_JM_CD=#{ksdJmCd,jdbcType=VARCHAR}
WHERE CORP_GR=#{corpGr} AND TR_YMD=TO_DATE(REPLACE(#{trYmd}, '-', ''), 'YYYYMMDD') AND TR_CD=#{trCd}
  AND FUND_CD=#{fundCd} AND TR_SEQ=#{trSeq}
